let PAR={weg:10,sec:35,tech:50,overn:25,ai:15,nd:2.5,pe:1.3,peg:1.5,doel:15,sl_add:4,sl_rem:2,sl_wk:2,sl_top:10};try{const o=JSON.parse(localStorage.getItem('pf_par')||'null');if(o)PAR=Object.assign(PAR,o)}catch(e){}
