 if(!L.length||!G)return ctl+`<div class="note" style="margin-top:12px">Nog niet genoeg transacties om gedrag te analyseren.</div>`;
 const P=["g","n","a"],Q=["Goed","Let op","Aandacht"],a=L.filter(x=>x.s===2);
