 sym={EUR:"€",USD:"$",GBP:"£",CAD:"C$",SEK:"kr",KZT:"₸",CHF:"CHF",DKK:"kr",NOK:"kr",TWD:"NT$",BRL:"R$"},cu=sym[v.cur]||v.cur||"",ml=n=>n==null?"–":cu+" "+(Math.abs(n)>=1000?(n/1000).toFixed(1).replace(".",",")+" mld":Math.round(n).toLocaleString("nl-NL")+" mln"),
