  const pay=pk(D.div_volgende),ex=pk(D.ex_div),yd=pay&&pay>now?pay:ex&&ex>now?ex:null,h=D.div_12m||[],reg=h.length>=3&&D.div_laatste_bedrag,lim=all?new Date(now.getTime()+200*864e5):new Date(ty,11,31,23,59);
