function vervangPairs(){
 const oo=own.filter(r=>r.eps!=null&&r.roic!=null&&r.peg!=null&&(holdM(r)==null||holdM(r)>=12)&&(r.eps<DOEL||(rmin3(r)!=null&&rmin3(r)<15))).map(r=>({r,s:rangR(r)})).sort((a,b)=>a.s-b.s);
 const cc=rows.filter(r=>r.watch&&r.trend!=="Downtrend"&&oordeelR(r).hc==="g"&&buitenkans(r)&&cscore(r).s>=CS_BK&&(r.fin?r.roe!=null&&r.roe>=RULES.roe:r.nd!=null&&r.nd<=1)).map(r=>({r,s:rangR(r)})).sort((a,b)=>b.s-a.s);
 const used=new Set(),out=[];
 for(const o of oo.slice(0,6)){if(out.length>=2)break;const c=cc.find(x=>!used.has(x.r.tk)&&cscore(x.r).s-cscore(o.r).s>=CS_DIFF&&x.r.eps>o.r.eps&&x.r.roic>o.r.roic&&(o.r.peg>=50||x.r.peg<o.r.peg)&&aiS(x.r)>=0&&aiS(x.r)>=aiS(o.r));if(!c)continue;used.add(c.r.tk);
  const A=o.r,B=c.r,w=[];
  if(B.eps>A.eps)w.push(`winstgroei ${f0(B.eps)}% per jaar tegenover ${f0(A.eps)}%`);
  if(B.roic>A.roic)w.push(`ROIC ${f0(B.roic)}% tegenover ${f0(A.roic)}%`);
  if(A.peg<50&&B.peg<A.peg)w.push(`PEG ${pgT(B.peg)} tegenover ${pgT(A.peg)}`);else if(A.peg>=50)w.push(`PEG ${pgT(B.peg)}, bij ${A.naam} is die niet te berekenen`);
  const bn=B.nd<=0?"netto cash":"schuld "+f1(B.nd)+"× EBITDA";if(A.nd!=null&&A.nd>B.nd)w.push(`${bn} tegenover ${A.nd<=0?"netto cash":f1(A.nd)+"×"} bij ${A.naam}`);else if(A.nd==null)w.push(bn);
  out.push({A,B,w,pt:cscore(B).s-cscore(A).s})}
 return out}
function vervangHTML(){const P=vervangPairs(),n=own.length;
 const kop=n>MAXPOS?`Je hebt ${n} aandelen en wilt naar maximaal ${MAXPOS}. Dat zijn er ${n-MAXPOS} te veel: verkoop eerst, koop daarna pas iets nieuws.`:`Je hebt ${n} aandelen en wilt er maximaal ${MAXPOS}.${n===MAXPOS?" Je zit op je maximum: koop alleen iets nieuws als je er één verkoopt.":""}`;
 return `<div class="note" style="margin:0 0 8px">${kop}</div><div class="note" style="margin:0 0 8px"><b>Houd het lang:</b> een voorstel verschijnt alleen als je het aandeel minstens een jaar hebt, het verschil meerdere jaren zichtbaar is in winst en ROIC, en de kandidaat ook de laatste 3 jaar een ROIC van minstens 15% haalde. Hooguit twee voorstellen tegelijk.</div>`+(P.length?P.map(x=>`<div class="cand" style="margin-bottom:10px"><div class="top2"><div class="note" style="margin:0">Vervang <button class="back" data-d="${x.A.tk}">${x.A.naam} ›</button> door <button class="back" data-d="${x.B.tk}">${x.B.naam} ›</button></div></div><ul>${x.w.map(t=>`<li>${t}</li>`).join("")}</ul><div class="note" style="margin:4px 0 0">${x.A.naam} weegt ${f1(x.A.w)}% van je portefeuille.</div><button class="row" data-s="vv${P.indexOf(x)}" style="margin-top:6px"><span class="grow"><div class="t">Volledige analyse</div></span><span class="m">›</span></button></div>`).join(""):`<div class="note">Op dit moment is geen enkele kandidaat duidelijk sterker dan je zwakste aandelen.</div>`)+`<div class="note">Dit rekent met je eigen regels: winstgroei, ROIC, PEG en schuld, met cash als pluspunt. Het is geen beleggingsadvies. Kosten van verkopen en kopen tellen mee, en een bedrijf met een slecht jaar kan terugkomen.</div>`}

function vervangDiep(x){const A=x.A,B=x.B,a=A.D||{},b=B.D||{};
 const pr=v=>v==null||!isFinite(v)?"–":f1(v*100)+"%",xx=v=>v==null||!isFinite(v)?"–":f1(v)+"×",nm=v=>v==null||!isFinite(v)?"–":f1(v);
 const rmin=d=>d.roic_reeks&&d.roic_reeks.length?Math.min(...d.roic_reeks.slice(-3)):null;
 const pe=(r,d)=>d.pe&&d.pe_hist?d.pe/d.pe_hist-1:null;
 const L=[["Winstgroei per jaar",a.eps_cagr,b.eps_cagr,1,pr],["Omzetgroei per jaar",a.rev_cagr,b.rev_cagr,1,pr],["Operationele marge",a.om,b.om,1,pr],["Vrije kasstroom, marge",a.fcf_marge,b.fcf_marge,1,pr],["Vrije kasstroom, yield",a.fcf_yield,b.fcf_yield,1,pr],["ROIC nu",a.roic,b.roic,1,pr],["ROIC, laagste van 3 jaar",rmin(a),rmin(b),1,pr],["PE tegenover eigen gemiddelde",pe(A,a),pe(B,b),-1,v=>v==null?"–":(v>=0?"+":"")+Math.round(v*100)+"%"],["PEG",A.peg<50?A.peg:null,B.peg<50?B.peg:null,-1,nm],["EV/EBITDA",a.ev_ebitda,b.ev_ebitda,-1,xx],["Schuld/EBITDA",a.nd_ebitda,b.nd_ebitda,-1,v=>v==null||!isFinite(v)?"–":(v<=0?"netto cash":f1(v)+"×")],["Dividend, yield",a.yld,b.yld,1,pr],["Koers per jaar, 5 jaar",a.koers_cagr5,b.koers_cagr5,1,pr],["Grootste daling, 5 jaar",a.dd5,b.dd5,1,pr],["Beta",a.beta,b.beta,-1,nm]];
 let wa=0,wb=0;
 const rowsH=L.map(([n,va,vb,dir,fm])=>{let ca="",cb="";if(va!=null&&vb!=null&&isFinite(va)&&isFinite(vb)&&va!==vb){const aw=(va-vb)*dir>0;if(aw){ca="pos";wa++}else{cb="pos";wb++}}return `<tr><td>${n}</td><td class="num ${ca}">${fm(va)}</td><td class="num ${cb}">${fm(vb)}</td></tr>`}).join("");
 const tbl=`<div class="sec"><h2>Kerncijfers naast elkaar</h2><div class="tile"><table class="t"><tr><th></th><th>${A.naam.split(" ")[0]}</th><th>${B.naam.split(" ")[0]}</th></tr>${rowsH}</table><div class="note">Groen is per regel de beste waarde. ${B.naam} wint ${wb} van ${wa+wb} regels, ${A.naam} ${wa}. Alle cijfers komen uit de jaarcijfers en koersen, geen schattingen van mij.</div></div></div>`;
 const rs=(r,d)=>d.roic_reeks&&d.rjaren?d.rjaren.slice(-d.roic_reeks.length).map((j,i)=>`${j}: ${f1(d.roic_reeks[i]*100)}%`).join(" · "):"niet beschikbaar";
 const roic=`<div class="sec"><h2>Rendement op kapitaal per jaar</h2><div class="tile"><div class="lbl">${A.naam}</div><div class="s" style="white-space:normal">${rs(A,a)}</div><div class="lbl" style="margin-top:10px">${B.naam}</div><div class="s" style="white-space:normal">${rs(B,b)}</div><div class="note">ROIC laat zien hoeveel winst een bedrijf maakt op het geld dat erin zit. Een dalende lijn betekent dat de voorsprong afneemt.</div></div></div>`;
 const w=A.w,secB=own.filter(r=>r.sector===A.sector).reduce((t,r)=>t+r.w,0),secN=own.filter(r=>r.sector===B.sector).reduce((t,r)=>t+r.w,0);
 const mA=own.filter(r=>r.munt===A.munt).reduce((t,r)=>t+r.w,0),mN=own.filter(r=>r.munt===B.munt).reduce((t,r)=>t+r.w,0);
 const tot=own.reduce((t,r)=>t+r.w,0);
 const sa=A.sector===B.sector,ma=A.munt===B.munt;
 const eff=`<div class="sec"><h2>Wat de wissel met je portefeuille doet</h2><div class="tile">${kvs([["Zelfde bedrag, weging",f1(w)+"%"],["Sector "+A.sector,f1(secB)+"% → "+f1(sa?secB:secB-w)+"%"],["Sector "+B.sector,f1(secN)+"% → "+f1(sa?secN:secN+w)+"%"],["Valuta "+A.munt,f1(mA)+"% → "+f1(ma?mA:mA-w)+"%"],["Valuta "+B.munt,f1(mN)+"% → "+f1(ma?mN:mN+w)+"%"],["Aantal aandelen",own.length+" → "+own.length]])}<div class="note">Een wissel van één op één verandert het aantal aandelen niet. Om van ${own.length} naar ${MAXPOS} te komen moet je daarnaast ${Math.max(0,own.length-MAXPOS)} aandelen verkopen zonder iets terug te kopen. Je grenzen: maximaal 10% per bedrijf en 35% per sector.${secN+(sa?0:w)>35?" Let op: na de wissel zit je boven je grens van 35% in "+B.sector+".":""}</div></div></div>`;
 const keepL=L.filter(([n,va,vb,dir])=>va!=null&&vb!=null&&isFinite(va)&&isFinite(vb)&&va!==vb&&(va-vb)*dir>0).map(l=>`<li>${l[0]}: ${l[4](l[1])} tegenover ${l[4](l[2])}</li>`).join("");
 const keep=`<div class="sec"><h2>Wat voor ${A.naam} pleit</h2><div class="tile">${keepL?`<ul style="margin:0;padding-left:18px">${keepL}</ul>`:'<div class="note" style="margin:0">Op geen enkel cijfer scoort het beter.</div>'}<div class="note">Dit zijn de regels waar je huidige aandeel beter scoort. ${A.r?"":""}Een wissel kost je spreads en transactiekosten, en het aandeel heeft ${A.p&&A.p.y!=null?"de afgelopen 12 maanden "+pc(A.p.y)+" gedaan":"zijn eigen verloop"}.</div></div></div>`;
 const warn=[];
 if(B.munt!=="EUR")warn.push("Valutarisico: "+B.naam+" noteert in "+B.munt+".");
 if(b.earnings){const dn=Math.round((new Date(b.earnings+"T12:00:00")-new Date())/864e5);if(dn>=0&&dn<=14)warn.push("Cijfers over "+dn+" dagen ("+b.earnings+"): wacht liever tot daarna.");else if(dn<0&&dn>=-14)warn.push("Cijfers zijn "+(-dn)+" dagen geleden verschenen ("+b.earnings+").")}
 if(b.eps_cagr!=null&&b.eps_cagr>.4)warn.push("Winstgroei van "+pr(b.eps_cagr)+" per jaar is hoog: dat komt vaak door herstel vanaf een lage winst en houdt zelden aan.");
 if(b.nd_ebitda!=null&&b.nd_ebitda>1)warn.push("Schuld van "+xx(b.nd_ebitda)+" EBITDA is meer dan je regel van 1×.");
 if(b.ins_pct!=null&&b.ins_pct<.01)warn.push("Insiders bezitten bijna niets ("+pr(b.ins_pct)+").");
 const risk=`<div class="sec"><h2>Aandachtspunten bij ${B.naam}</h2><div class="tile"><ul style="margin:0;padding-left:18px">${warn.map(t=>`<li>${t}</li>`).join("")||"<li>Geen opvallende aandachtspunten.</li>"}</ul></div></div>`;
 const aiA=aiOf(A),aiB=aiOf(B),nmA={2:"Profiteert sterk",1:"Profiteert",0:"Neutraal","-1":"Kwetsbaar"};
 const aiBox=(r,x)=>{const v=AIV[r.tk],nt=aiN(r),NM={2:"Profiteert sterk",1:"Profiteert",0:"Neutraal","-1":"Kwetsbaar","-2":"Zeer kwetsbaar"};return `<div class="lbl">${r.naam}${x?" · netto "+(NM[nt]||"").toLowerCase():""}</div>${x?`<div style="margin-top:6px;white-space:normal;line-height:1.45"><b>Blootstelling (streng gewogen):</b> ${x[1]}. ${x[2]}</div><div class="note" style="margin:4px 0 0"><b>Risico:</b> ${x[3]||""}</div>${v?`<div style="margin-top:8px;white-space:normal;line-height:1.45"><b>Kan het bedrijf zelf winnen met AI?</b> ${v[0]>=1?"Sterk verweer.":v[0]<0?"Zwak verweer.":"Matig verweer."} ${v[1]}</div>`:`<div class="note" style="margin:6px 0 0">Eigen verweer nog niet beoordeeld.</div>`}`:`<div class="note" style="margin:4px 0 0">Hier heb ik nog geen AI-beoordeling voor. Daardoor vergelijk ik dit bedrijf alleen op cijfers.</div>`}`};
 const sA=aiS(A),sB=aiS(B);
 const aiV=sB<sA?`Netto, na het eigen verweer, scoort ${B.naam} slechter dan ${A.naam}. Dat weegt zwaar, want de cijfers kijken terug en AI kijkt vooruit.`:sB>sA?`Netto, na het eigen verweer, scoort ${B.naam} beter dan ${A.naam}: dat versterkt het voorstel.`:`Netto scoren ze gelijk op AI, dus de cijfers geven de doorslag.`;
 const ai=`<div class="sec"><h2>Toekomst en AI</h2><div class="tile">${aiBox(A,aiA)}<div style="height:12px"></div>${aiBox(B,aiB)}<div class="note"><b>${aiV}</b> Ik weeg de blootstelling streng en laat het eigen verweer alleen meetellen als het sterk is. Dit is mijn oordeel over het bedrijfsmodel, geen cijfer en geen voorspelling. Het kan verkeerd uitpakken, in beide richtingen.</div></div></div>`;
 const mA2=holdM(A),r3A=rmin3(A),r3B=rmin3(B);
 const lt=[[ "Je bezit "+A.naam+" al lang genoeg", mA2==null?"onbekend":mA2>=12?"ja, ongeveer "+Math.round(mA2)+" maanden":"nee, pas "+Math.round(mA2)+" maanden: geef het meer tijd", mA2==null||mA2>=12],["Het verschil bestaat al meerdere jaren","ROIC van de laatste 3 jaar, laagste jaar: "+(r3A==null?"–":f1(r3A)+"%")+" tegenover "+(r3B==null?"–":f1(r3B)+"%")+(r3A!=null&&r3B!=null&&r3B-r3A>=5?". Dat is structureel.":". Dat verschil is klein."),r3A!=null&&r3B!=null&&r3B-r3A>=5],["Winstgroei over meerdere jaren",f0(B.eps)+"% per jaar tegenover "+f0(A.eps)+"%, het doel is "+DOEL+"%.",B.eps>=DOEL&&A.eps<DOEL],["AI, netto na eigen verweer",(aiS(B)>=aiS(A)?"niet slechter dan":"slechter dan")+" "+A.naam,aiS(B)>=aiS(A)]];
 const ltH=`<div class="sec"><h2>Langetermijncheck</h2><div class="tile">${lt.map(x=>`<div style="display:flex;gap:8px;padding:6px 0;border-top:1px solid var(--line)"><span class="${x[2]?"pos":"neg"}" style="width:18px">${x[2]?"✓":"✗"}</span><span class="grow" style="white-space:normal"><b>${x[0]}</b><div class="note" style="margin:2px 0 0">${x[1]}</div></span></div>`).join("")}<div class="note">Alleen wisselen als dit geen korte-termijnverschil is. Koersbewegingen van de laatste maanden en trends zeggen weinig over hoe een bedrijf over vijf of tien jaar scoort, dus die tellen hier niet mee. Wacht bij twijfel een jaar. Elke wissel kost transactiekosten en je hoort meer te winnen dan dat.</div></div></div>`;
 const conc=`<div class="tile" style="margin-top:12px"><div class="lbl">Conclusie op je eigen regels</div><div style="margin-top:6px;white-space:normal;line-height:1.45">${B.naam} scoort ${f1(x.pt)} punten hoger dan ${A.naam} op winstgroei, ROIC, PEG en schuld, en wint ${wb} van ${wa+wb} cijferregels. Op de langetermijncheck haalt het voorstel ${lt.filter(x=>x[2]).length} van ${lt.length} toetsen. De wissel is alleen zinvol als je ${B.naam} echt begrijpt en de aandachtspunten hieronder je niet afschrikken.</div></div>`;
 return conc+ltH+ai+tbl+roic+eff+keep+risk+`<div class="note">Dit is een rekensom op je eigen regels en geen beleggingsadvies. Kosten van kopen en verkopen tellen mee, en wat een bedrijf in het verleden deed zegt niet wat het straks doet.</div>`}

function wegTxt(r){const s=streef(r);if(!s)return "Geen weging-advies beschikbaar.";const nu=f1(r.w);
 if(s.d>0.4)return `Nu ${nu}% van je portefeuille. Dit aandeel verdient een grotere weging: streef naar ${f1(s.t)}% (+${f1(s.d)} punt, ongeveer ${eur(s.d/100*TOT)}). Reden: ${r.naam} ${s.why}. ${n12()>2*own.length?"Je zit boven je richtlijn voor trades, dus doe dit met je volgende storting en in weinig stappen.":"Doe dit liefst met je volgende stortingen."}`;
 if(s.d<-0.4)return `Nu ${nu}% van je portefeuille. Dit aandeel mag kleiner: streef naar ${f1(s.t)}% (${f1(s.d)} punt, ongeveer ${eur(-s.d/100*TOT)} minder). Reden: ${r.naam} ${s.why}.`;
 return `Nu ${nu}% van je portefeuille. Houd de weging zoals die is.${s.why?" Reden: "+r.naam+" "+s.why+".":""}`}
const AVG=[["Verkoop overwegen","Heroverwegen"],["Behouden, let op","Behouden, let op"],["Volgen","Volgen"],["Behouden of bijkopen","Behouden of bijkopen"],["Behouden","Behouden"]];
function elab(x){return x.v.lab==="Behouden of bijkopen"&&x.s&&x.s.tier!=="uitbouwen"?"Behouden":x.v.lab}
function n12(){try{const c=new Date(Date.now()-365*864e5).toISOString().slice(0,10);return PRIVE.imp.trx.x.filter(x=>x[0]>=c&&x[8]!==0).length}catch(e){return null}}
function rustBlok(){const n=n12(),lim=2*own.length;if(n==null||n<=lim)return "";return `<div class="tile" style="margin-top:10px;border-left:4px solid var(--a,#d9822b)"><div class="lbl">Rust in je portefeuille</div><div class="note" style="margin:4px 0 0">${n} trades in de laatste 12 maanden. Je eigen richtlijn is hooguit 2 per aandeel, dus ${lim}. Doe even rustig aan met kopen en verkopen: vaak handelen kost geld en past niet bij lang vasthouden.</div></div>`}
document.addEventListener("click",e=>{try{const t=e.target.closest("[data-at]");if(t){advTab=t.dataset.at;e.stopPropagation();render();return}const q=e.target.closest("[data-atset]");if(q)advTab=q.dataset.atset}catch(x){}},true);
function kandV(){const k=kandidaten().sort((a,b)=>cscore(b.r).s-cscore(a.r).s||b.s-a.s),VB=vervangPairs().map(x=>x.B.tk);return k.filter(x=>x.r.watch?VB.includes(x.r.tk):(()=>{const s=streef(x.r);return s&&s.tier==="uitbouwen"})())}
function adviesBlok(){const {up,dn,rv}=advActs(),VP=vervangPairs();
 const rows=[...up.slice(0,2).map(x=>[x.r.naam+" bijkopen"+(x.s.ex?" (buitenkans)":""),f1(x.r.w)+"% → "+f1(x.s.t)+"%","g"]),...dn.slice(0,1).map(x=>[x.r.naam+" verkleinen",f1(x.r.w)+"% → "+f1(x.s.t)+"%","a"]),...rv.slice(0,1).map(x=>{const i=VP.findIndex(p=>p.A.tk===x.r.tk);return [x.r.naam+" heroverwegen",i>=0?"vervanger: "+VP[i].B.naam:f1(x.r.w)+"%","r"]})];
 const tot=up.length+dn.length+rv.length,rest=tot-rows.length;
 return `<div class="sec"><div class="tile" style="padding:0"><button class="row" data-t="doel" data-atset="nu" style="border:0;background:none;width:100%;text-align:left"><span class="grow"><div class="t" style="font-size:17px">Wat nu</div><div class="m">${tot?tot+" stappen volgens je regels":"geen actie nodig"} · tik voor bedragen en redenen</div></span><span class="m">›</span></button>${rows.length?`<div style="padding:0 16px 14px">${rows.map(([t,r,c])=>`<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;padding:6px 0"><span class="pill ${c}" style="white-space:normal">${t}</span><span class="num" style="white-space:nowrap">${r}</span></div>`).join("")}${rest>0?`<div class="note" style="margin:4px 0 0">en nog ${rest} andere ›</div>`:""}</div>`:""}</div></div>`}

function adviesSub(){const v=own.map(r=>({r,v:verdict(r),s:streef(r)}));
 return (own.length>MAXPOS||(n12()||0)>2*own.length?`<div class="note" style="margin:8px 0 0">${own.length>MAXPOS?"Je hebt "+own.length+" aandelen en wilt maximaal "+MAXPOS+": nieuw geld gaat liever naar bestaande winnaars dan naar nieuwe namen. ":""}${(n12()||0)>2*own.length?"Je zit met "+n12()+" trades in 12 maanden boven je richtlijn van "+2*own.length+": kies dus weinig, grote stappen.":""}</div>`:"")+AVG.map(([lab,t])=>{const L=v.filter(x=>elab(x)===lab).sort((a,b)=>b.r.w-a.r.w);if(!L.length)return "";const o=!!dOpen["av"+lab];
  return `<div class="tile" style="margin-top:10px;padding:0"><button class="row" data-dx="av${lab}" aria-expanded="${o}" style="border:0;background:none;width:100%;border-radius:12px"><span class="grow"><div class="t">${t}</div></span><span class="num m">${L.length}</span><span class="m">${o?"˄":"˅"}</span></button>${o?`<div style="padding:0 12px 12px">${L.map(x=>{const d=x.s?x.s.d:0;return `<button class="row" data-d="${x.r.tk}"><span class="grow"><div class="t">${x.r.naam}</div><div class="m">weging ${f1(x.r.w)}%${x.s&&Math.abs(d)>0.4?" → "+f1(x.s.t)+"%":" · houden"}</div></span><span class="m">›</span></button>`}).join("")}</div>`:""}</div>`}).join("")+`<div class="note" style="margin-top:12px">Tik een aandeel voor de volledige analyse. De streefweging is een rekenvoorbeeld op je eigen regels: compounder-score, moat, waardering en je grens van ${PAR.weg}% per bedrijf. Het is geen beleggingsadvies.</div>`}

const MEGA={"NVDA":"AI en chips","TSM":"AI en chips","ASML.AS":"AI en chips","ASM.AS":"AI en chips","BESI.AS":"AI en chips","APH":"AI en chips","MSFT":"AI en cloud","GOOGL":"AI en cloud","AMZN":"AI en cloud","STRL":"AI en cloud","META":"AI en cloud","ADYEN.AS":"Digitaal betalen","KSPI":"Digitaal betalen","NU":"Digitaal betalen","MELI":"Digitaal betalen","FTNT":"Cybersecurity","ISRG":"Gezondheid en vergrijzing","HEI":"Luchtvaart en defensie","SPGI":"Data en software","RACE.MI":"Luxe en vermogende consument","CSU.TO":"Software","TOI.V":"Software","LMN.V":"Software","BKNG":"Reizen","NFLX":"Streaming","SFM":"Gezonde voeding","AF.PA":"Luchtvaart en defensie"};

// Beoordelingen die de geplande taak in beoordelingen.json zet (moat, AI, omschrijving, megatrend)
(function(){const B=window.BEO||{};Object.assign(NLO,B.nlo||{});Object.assign(MOAT,B.moat||{});Object.assign(AIX,B.aix||{});Object.assign(AIV,B.aiv||{});Object.assign(MEGA,B.mega||{})})();
rows.forEach(r=>{if(r.ai&&r.ai[1]==="Nog te beoordelen"&&AIX[r.tk])r.ai=AIX[r.tk]});
// Nieuwe namen zonder volledige beoordeling tellen nergens mee tot die er is
rows.forEach(r=>{r.score=cscore(r).s;r.licht=r.score>=CS_COMP?"g":r.score>=5?"a":"r"});
const WACHT=rows.filter(r=>r.watch&&!(MOAT[r.tk]&&AIX[r.tk]&&NLO[r.tk]));
WACHT.forEach(r=>rows.splice(rows.indexOf(r),1));
function filoData(){const W=own.reduce((t,r)=>t+r.w,0)||100,sh=f=>own.filter(f).reduce((t,r)=>t+r.w,0)/W*100;
 const mo=r=>{const m=MOAT[r.tk];return m&&/breed|matig/i.test(m.s)};
 let n12=0,kost=0;try{const c=new Date(Date.now()-365*864e5).toISOString().slice(0,10);PRIVE.imp.trx.x.forEach(x=>{if(x[0]>=c){if(x[8]!==0)n12++;kost+=(x[2]||0)+(x[3]||0)}})}catch(e){n12=null}
 const g=(v,a,b)=>v>=a?"g":v>=b?"a":"r";
 const yr=REAL&&REAL.xirr!=null?REAL.xirr:null;
 const s1=sh(r=>r.eps>=DOEL),s2=sh(mo),s3=sh(r=>r.roic!=null&&r.roic>=15),s4=sh(r=>r.peg>0&&r.peg<=1.5),s6=sh(r=>r.nd!=null&&r.nd<=1),s6u=sh(r=>r.nd==null),s7=sh(r=>(r.D&&r.D.fcf_cagr!=null?r.D.fcf_cagr>0:false)&&r.eps>0),s8=sh(r=>(r.D&&r.D.ins_pct>=.05)||r.eigenaar==="oprichter"||r.eigenaar==="familie");
 const lim=2*own.length;
 const s9=sh(r=>r.D&&r.D.rev_cagr!=null&&r.D.rev_cagr>=.10),s10=sh(r=>!!MEGA[r.tk]),s11=sh(r=>aiN(r)>=0);
 return [
 ["Groei van "+DOEL+"% per jaar",f1(s1)+"% van je geld groeit zelf "+DOEL+"% of meer"+(yr!=null?". Je eigen resultaat sinds 2016: "+pc(yr)+" per jaar.":"."),g(s1,70,50)],
 ["Duidelijke moat",f1(s2)+"% van je geld zit in bedrijven met een brede of matige moat (mijn beoordeling).",g(s2,70,50)],
 ["Winnaar in de sector (ROIC vanaf 15%)",f1(s3)+"% van je geld zit in bedrijven met een ROIC van 15% of meer. Een hoge ROIC is het cijfer dat het dichtst bij 'echte winnaar' komt.",g(s3,70,50)],
 ["Redelijke prijs (PEG tot 1,5)",f1(s4)+"% van je geld staat tegen een PEG van 1,5 of lager. Kwaliteit mag een premie kosten, maar de PEG moet te verdedigen blijven.",g(s4,60,40)],
 ["Weinig handelen",n12==null?"Zonder je trades niet te meten.":n12+" trades in de laatste 12 maanden (een order die DeGiro in delen uitvoert telt als 1 trade), kosten "+eur(kost)+". Richtlijn: hooguit 2 per aandeel per jaar, dus "+lim+".",n12==null?"a":n12<=lim?"g":n12<=2*lim?"a":"r"],
 ["Spreiding",own.length+" aandelen (maximum "+MAXPOS+"). Je vijf grootste posities zijn samen "+f1([...own].sort((a,b)=>b.w-a.w).slice(0,5).reduce((t,r)=>t+r.w,0)/W*100)+"% van je geld. Je grens is "+PAR.weg+"% per bedrijf.",own.length<=MAXPOS?"g":"a"],
 ["Weinig, goed begrepen bedrijven","De beleggers die je volgt, houden meestal minder posities. Jouw grens van "+PAR.weg+"% per bedrijf is een bewuste keuze voor spreiding. Dit is mijn inschatting, geen cijfer.","n"],
 ["Weinig schuld of netto cash",f1(s6)+"% van je geld heeft hooguit 1× EBITDA schuld"+(s6u>0?"; bij "+f1(s6u)+"% is het cijfer niet beschikbaar":"")+".",g(s6,60,40)],
 ["Groeiende kasstroom en winst",f1(s7)+"% van je geld groeit zowel in kasstroom als in winst per aandeel.",g(s7,70,50)],
 ["Management met eigen geld erin",f1(s8)+"% van je geld zit in bedrijven met insiders vanaf 5% of een oprichter- of familie-eigenaar.",g(s8,40,25)],
 ["Lange runway: omzet groeit snel",f1(s9)+"% van je geld zit in bedrijven met een omzetgroei van 10% of meer per jaar. Hoge omzetgroei laat zien dat de markt nog ruimte heeft.",g(s9,60,40)],
 ["Megatrend in de rug",f1(s10)+"% van je geld zit in bedrijven die ik aan een duidelijke megatrend koppel (AI en chips, betalen, cybersecurity, vergrijzing, defensie). Dit is mijn oordeel, geen cijfer.",g(s10,60,40)],
 ["Toekomstbestendig tegen AI",f1(s11)+"% van je geld zit in bedrijven die netto niet kwetsbaar zijn voor AI, na hun eigen verweer. Ook dit is mijn oordeel over het bedrijfsmodel.",g(s11,80,60)]]}
function filoBlok(){const D=filoData(),n=D.filter(x=>x[2]==="g").length;return `<button class="tile go" data-s="filo" style="margin-top:8px;width:100%;text-align:left"><div class="lbl">Jouw beleggingsfilosofie</div><div class="v num">${n} van ${D.length} <span style="font-size:14px;font-weight:500">principes op groen</span></div><div class="note" style="margin:4px 0 0">Tik voor hoe je portefeuille scoort op groei, moat, prijs, rust, schuld, kasstroom en eigenaarschap ›</div></button>`}
function filoSub(){const D=filoData();return `<div class="note" style="margin-top:8px">Lang beleggen in een beperkt aantal bedrijven die ik goed begrijp: een duidelijke moat, een hoge ROIC met veel ruimte om winst opnieuw te investeren, weinig schuld en een eerlijk bestuur met eigen geld erin, tegen een redelijke prijs. Geduld en weinig handelen. Winnaars krijgen de ruimte om door te groeien: geen trimadvies, alleen niet extra bijkopen. Pas als een positie echt extreem buitensporig wordt, beslis jij zelf. Nieuwe inleg gaat eerst naar bedrijven die je al hebt; een nieuwe naam komt er alleen bij als hij duidelijk beter is. Doel: ${DOEL}% per jaar. Hieronder zie je hoe je portefeuille nu scoort, op echte cijfers.</div>${(()=>{const J=/^(Duidelijke moat|Megatrend|Toekomstbestendig|Weinig, goed)/,rw=x=>`<div class="row" style="align-items:flex-start"><span class="dot ${x[2]}" style="margin-top:6px"></span><span class="grow"><div class="t">${x[0]}</div><div class="m" style="white-space:normal">${x[1]}</div></span></div>`;return `<div class="lbl" style="margin-top:12px">Op echte cijfers</div><div class="list">${D.filter(x=>!J.test(x[0])).map(rw).join("")}</div><div class="lbl" style="margin-top:12px">Mijn inschatting (geen cijfers)</div><div class="list">${D.filter(x=>J.test(x[0])).map(rw).join("")}</div>`})()}<div class="sec"><h2>Jouw regels op één plek</h2><div class="tile"><div class="note" style="margin:0">Alle schermen gebruiken dezelfde regels: winstgroei vanaf ${RULES.eps}%, ROIC vanaf ${RULES.roic}% (nieuwe kandidaten vanaf ${RULES.roicIn}%), PEG tot ${RULES.peg}, schuld tot ${RULES.nd}× EBITDA voor kandidaten, maximaal ${MAXPOS} aandelen, AI-thema's samen hooguit ${RULES.mega}% en niet meer dan ${PAR.weg}% per bedrijf. Een aandeel krijgt alleen extra geld als het aan al deze regels voldoet. Uitzondering voor buitenkansen: een aandeel met PEG tot ${RULES.bk.peg}, ROIC vanaf ${RULES.bk.roic}%, winstgroei vanaf ${RULES.bk.eps}% en een ROIC van minstens ${RULES.bk.rmin}% in alle drie de laatste jaren mag boven de grens van een cluster, sector of AI-thema's uit, tot ${RULES.bk.extra} procentpunt erboven. Dan voeg je maximaal ${RULES.bk.plus} punt weging toe. Daarboven blijft het dicht.</div></div></div><div class="note">Groen, oranje of rood is mijn eigen drempel (bijvoorbeeld groen vanaf 70% van je geld). Het zijn richtlijnen en geen regels.</div>`}

function megaH(){const W=own.reduce((t,r)=>t+r.w,0)||100,G={};own.forEach(r=>{const k=MEGA[r.tk]||"Geen duidelijke megatrend";(G[k]=G[k]||[]).push(r)});
 const E=Object.entries(G).map(([k,l])=>[k,l,l.reduce((t,r)=>t+r.w,0)/W*100]).sort((a,b)=>(a[0]==="Geen duidelijke megatrend")-(b[0]==="Geen duidelijke megatrend")||b[2]-a[2]);
 return `<div class="sec"><h2>Welke megatrend zit achter je geld</h2><div class="tile">${E.map(([k,l,w])=>{const o=!!dOpen["mg"+k];return `<button class="row" data-dx="mg${k}" aria-expanded="${o}" style="border:0;background:none;width:100%"><span class="grow"><div class="t">${k}</div><div class="m">${l.length} bedrijven</div></span><span class="num">${f1(w)}%</span><span class="m">${o?"˄":"˅"}</span></button>${o?`<div style="padding:0 12px 8px">${l.sort((a,b)=>b.w-a.w).map(r=>`<button class="row" data-d="${r.tk}"><span class="grow"><div class="t">${r.naam}</div></span><span class="num">${f1(r.w)}%</span></button>`).join("")}</div>`:""}`}).join("")}<div class="note">Dit is mijn indeling op basis van wat een bedrijf doet, geen cijfer. Veel geld in één megatrend, zoals AI, betekent dat die bedrijven vaak samen bewegen.</div></div></div>`}

function pgT(v){return v==null||!(v>0)||v>=90?"n.v.t.":f1(v)}

function verdict(r){const v=verdict0(r);if(!v||v.k==="structureel")return v;const s=streef(r);if(s&&s.tier!=="uitbouwen"&&/bijkopen/i.test(v.wat||"")){const lab=v.lab==="Behouden of bijkopen"?"Behouden":v.lab,cl=v.lab==="Behouden of bijkopen"?"g":v.cl;return Object.assign({},v,{lab,cl,wat:v.wat.replace("De waardering maakt bijkopen mogelijk.","Bijkopen hoeft nu niet.").replace(/bijkopen kan/g,"bijkopen hoeft nu niet")+(s.why?" Reden: "+r.naam+" "+s.why+".":"")})}return v}

let advTab="ov";
function advTabs(){const T=[["ov","Overzicht"],["nu","Wat nu"],["aand","Per aandeel"],["pf","Portefeuille"],["vv","Vervangen"],["filo","Filosofie"]];return `<div class="seg" style="margin-top:8px;display:grid;grid-template-columns:repeat(3,1fr);gap:4px">${T.map(([k,t])=>`<button data-at="${k}" aria-pressed="${advTab===k}" style="padding:9px 4px;white-space:nowrap">${t}</button>`).join("")}</div>`}
function advActs(){const L=own.map(r=>({r,v:verdict(r),s:streef(r)})).filter(x=>x.s);
 const up=L.filter(x=>x.s.d>0.4&&x.s.tier==="uitbouwen").sort((a,b)=>(b.s.z-a.s.z)||(b.s.d-a.s.d));
 const dn=L.filter(x=>x.s.d<-0.4&&x.s.tier!=="afbouwen").sort((a,b)=>a.s.d-b.s.d);
 const rv=L.filter(x=>x.v.k==="structureel");return {L,up,dn,rv}}
function rvZin(r){const p=[];p.push("winst "+epsT(r));p.push("ROIC "+(r.roic==null?"n.v.t.":f1(r.roic)+"%"));p.push("PEG "+pgT(r.peg));p.push(r.fin?"ROE "+(r.roe==null?"n.v.t.":f1(r.roe)+"%"):"schuld "+(r.nd==null?"n.v.t.":f1(r.nd)+"×"));const sl=[];if(epsOk(r)&&r.eps!=null&&r.eps<RULES.eps)sl.push("groeit onder je doel van "+RULES.eps+"%");if(r.roic!=null&&r.roic<RULES.roic)sl.push("rendeert onder je ROIC-grens van "+RULES.roic+"%");if(r.peg>RULES.peg&&pgT(r.peg)!=="n.v.t.")sl.push("is duur voor de groei");if(r.nd!=null&&r.nd>1.5)sl.push("heeft veel schuld");return r.naam+": "+p.join(", ").replace(/\.$/,"")+(sl.length?". Zwak, want het "+sl.join(" en ")+".":".")}
function advNu(){const {L,up,dn,rv}=advActs(),VP=vervangPairs(),nr=(x,i)=>`<span style="font-weight:700;margin-right:8px">${i}</span>`;let n=0;
 const kaart=(x,kop,reg,extra,cl)=>`<button class="tile" data-d="${x.r.tk}" style="display:block;width:100%;text-align:left;margin-top:10px"><div style="display:flex;justify-content:space-between;gap:8px"><div class="t">${nr(x,++n)}<span class="pill ${cl}" style="white-space:normal">${kop}</span></div><span class="num" style="white-space:nowrap">${reg}</span></div>${extra}</button>`;
 const sumUp=up.reduce((t,x)=>t+x.s.d/100*TOT,0),sumDn=dn.reduce((t,x)=>t-x.s.d/100*TOT,0);
 const tg=x=>rv.some(y=>y.r.tk===x.r.tk)?x.r.w:x.s.t,T=L.reduce((t,x)=>t+(up.some(y=>y.r.tk===x.r.tk)||dn.some(y=>y.r.tk===x.r.tk)?x.s.t:x.r.w),0)||100;
 const ai1=aiShare(),ai2=L.filter(x=>/^AI /.test(MEGA[x.r.tk]||"")).reduce((t,x)=>t+(up.some(y=>y.r.tk===x.r.tk)||dn.some(y=>y.r.tk===x.r.tk)?x.s.t:x.r.w),0)/T*100;
 let h=`<div class="note" style="margin:4px 0 0">Concrete stappen volgens je eigen regels, in volgorde van belang. Bedragen zijn de weging maal je portefeuillewaarde.</div>`;
 h+=up.slice(0,5).map(x=>kaart(x,x.r.naam+" bijkopen"+(x.s.ex?" · buitenkans":""),f1(x.r.w)+"% → "+f1(x.s.t)+"%",`${brkBand(x.r)}<div style="margin-top:4px;font-size:14px;font-weight:400">ongeveer ${eur(x.s.d/100*TOT)} erbij${INLEG>0?", ongeveer "+(m=>m+(m===1?" maand":" maanden"))(Math.max(1,Math.round(x.s.d/100*TOT/INLEG)))+" van je storting":""}</div><div class="note" style="margin:4px 0 0;font-weight:400">${x.r.naam} ${x.s.why}.</div>`,"g")).join("");
 h+=dn.map(x=>kaart(x,x.r.naam+" verkleinen",f1(x.r.w)+"% → "+f1(x.s.t)+"%",`<div style="margin-top:4px;font-size:14px;font-weight:400">ongeveer ${eur(-x.s.d/100*TOT)} minder</div><div class="note" style="margin:4px 0 0;font-weight:400">${x.r.naam} ${x.s.why}. Het vrijgekomen geld kan naar je bijkopen.</div>`,"a")).join("");
 h+=rv.map(x=>{const i=VP.findIndex(p=>p.A.tk===x.r.tk);return kaart(x,x.r.naam+" heroverwegen",f1(x.r.w)+"%",`<div class="note" style="margin:4px 0 0;font-weight:400">${rvZin(x.r)}${i>=0?" Zie het vervangingsvoorstel bij Vervangen.":""}</div>`,"r")}).join("");
 if(!n)h+=`<div class="tile" style="margin-top:10px"><div class="note" style="margin:0">Op dit moment geen actie nodig volgens je regels.</div></div>`;
 h+=`<div class="sec"><h2>Zo ziet je portefeuille eruit na deze stappen</h2><div class="tile">${kvs([["Aandelen",own.length+" (max "+MAXPOS+")"],["AI-thema's",f1(ai1)+"% → "+f1(ai2)+"%"],["Grens AI",RULES.mega+"%"]])}<div class="note" style="margin:8px 0 0">${sumUp>0?"Bijkopen samen ongeveer "+eur(sumUp)+". ":""}${sumDn>0?"Vrij uit verkleinen ongeveer "+eur(sumDn)+". ":""}${n12()!=null?"Trades in de laatste 12 maanden: "+n12()+" (richtlijn "+2*own.length+"). Doe dit dus in weinig stappen.":""}</div></div></div>`;
 return h}
function advAand(){const NM={2:"Profiteert sterk",1:"Profiteert",0:"Neutraal","-1":"Kwetsbaar","-2":"Zeer kwetsbaar"},pc1=v=>v==null?"n.v.t.":f1(v)+"%";
 return `<div class="note" style="margin:4px 0 8px">Tik een aandeel open voor cijfers, mijn inschatting en het advies. Tik de naam voor de volledige analyse.</div><div class="tile" style="padding:0">${[...own].sort((a,b)=>b.w-a.w).map(r=>{const v=verdict(r),s=streef(r),o=!!dOpen["ap"+r.tk],M=MOAT[r.tk];
  return `<button class="row" data-dx="ap${r.tk}" aria-expanded="${o}" style="border:0;background:none;width:100%"><span class="grow"><div class="t">${r.naam}</div><div class="m"><span class="pill ${v.cl}">${v.lab}</span> ${s?f1(r.w)+"% → "+f1(s.t)+"%":f1(r.w)+"%"}</div></span><span class="m">${o?"˄":"˅"}</span></button>${o?`<div style="padding:0 14px 12px">${kvs([["Winst/jr",epsT(r)],["ROIC",pc1(r.roic)],[r.fin?"ROE":"Schuld",r.fin?(r.roe==null?"n.v.t.":f1(r.roe)+"%"):(r.nd==null?"n.v.t.":f1(r.nd)+"×")],["PEG",pgT(r.peg)],["Kasstroom/jr",pc1(r.fcf)],["Omzet/jr",r.D&&r.D.rev_cagr!=null?pc1(r.D.rev_cagr*100):"n.v.t."]])}<div class="lbl" style="margin-top:10px">Mijn inschatting (geen cijfers)</div><div class="note" style="margin:2px 0">Moat: ${M?M.s:"niet beoordeeld"} · Megatrend: ${MEGA[r.tk]||"geen duidelijke"} · AI: ${(NM[aiN(r)]||"neutraal").toLowerCase()}</div>${brkBand(r)}<div class="lbl" style="margin-top:10px">Advies</div><div class="note" style="margin:2px 0">${wegTxt(r)}</div><button class="back" data-d="${r.tk}" style="margin-top:8px">Volledige analyse ›</button></div>`:""}`}).join('<div style="height:1px;background:var(--line)"></div>')}</div>`}
function advPf(){const zw=[...own].filter(r=>r.eps!=null).sort((a,b)=>((verdict(b).k==="structureel")-(verdict(a).k==="structureel"))||rangR(a)-rangR(b)).slice(0,Math.max(3,own.length-MAXPOS+1));const te=own.length-MAXPOS,n=n12(),lim=2*own.length;
 return `<div class="sec"><h2>Aantal aandelen</h2><div class="tile">${kvs([["Nu",String(own.length)],["Maximum",String(MAXPOS)],[te>0?"Te veel":"Ruimte",String(Math.abs(te))]])}<div class="note" style="margin:8px 0 0">${te>0?"Om op "+MAXPOS+" uit te komen moeten er "+te+" weg. Dit zijn de zwakste kandidaten op mijn kwaliteitsscore (winstgroei, ROIC, PEG, schuld). Je beslist zelf:":"Je zit binnen je maximum."}</div>${te>0?zw.map(r=>`<button class="row" data-d="${r.tk}"><span class="grow"><div class="t">${r.naam}</div><div class="m">winst ${f1(r.eps)}% · ROIC ${r.roic==null?"n.v.t.":f1(r.roic)+"%"} · PEG ${pgT(r.peg)}</div></span><span class="num">${f1(r.w)}%</span></button>`).join(""):""}</div></div>`
 +megaH()+`<div class="sec"><h2>Rust</h2><div class="tile"><div class="note" style="margin:0">${n==null?"Zonder je trades niet te meten.":n+" trades in de laatste 12 maanden. Je richtlijn is hooguit "+lim+" (2 per aandeel). "+(n>lim?"Je zit er boven, dus kies weinig, grote stappen.":"Je zit binnen je richtlijn.")}</div></div></div>`}
function advBody(){return advTab==="aand"?advAand():advTab==="pf"?advPf():advTab==="vv"?`<div class="sec" style="margin-top:10px"><div class="tile">${vervangHTML()}</div></div>`:advTab==="filo"?filoSub():advNu()}
function advSheet(){return advTabs()+advBody()}
function vDoel(){const h=head("Doelcheck");if(advTab==="ov"){let s=vDoel0();if(s.startsWith(h))s=s.slice(h.length);return h+advTabs()+s}return h+advTabs()+advBody()}

try{window.__parse={parseAccount,parseTrx}}catch(e){}

function brkAll(){try{const L=(window.DATA&&window.DATA.uitzonderlijk)||[],nu=Date.now();return L.filter(x=>x&&x.tk&&x.datum&&(nu-new Date(x.datum).getTime())<=21*864e5)}catch(e){return []}}
function brkVoor(tk){return brkAll().filter(x=>x.tk===tk)}
function brkKaart(x,kort){const nm=(rows.find(r=>r.tk===x.tk)||{}).naam||x.naam||x.tk;const dt=new Date(x.datum).toLocaleDateString("nl-NL",{day:"numeric",month:"long"});
 return `<div class="tile" style="margin-top:10px;border-left:4px solid var(--bad,#c0392b)"><div class="lbl" style="color:var(--bad,#c0392b);font-weight:700">Uitzonderlijk nieuws · ${nm} · ${dt}</div><div class="t" style="margin-top:4px;white-space:normal">${x.titel}</div><div class="note" style="margin:6px 0 0">${kort?x.tekst.split(". ")[0]+". Tik voor de details.":x.tekst}</div>${kort?"":`<div class="note" style="margin:8px 0 0">Dit nieuws staat er als toevoeging. Het advies en de cijfers van de app zijn er niet door aangepast; de afweging is aan jou.</div>${(x.bronnen||[]).length?`<div class="note" style="margin:8px 0 0">Bronnen: ${x.bronnen.map(b=>`<a href="${b.url}" target="_blank" rel="noopener">${b.naam}</a>`).join(" · ")}</div>`:""}`}${x.auto?`<div class="note" style="margin:6px 0 0">Automatisch herkend: ${x.reden||""}</div>`:""}</div>`}
function brkStart(){return "";const L=brkAll();if(!L.length)return "";return `<div class="sec" style="margin-top:8px">${L.map(x=>`<button data-d="${x.tk}" style="display:block;width:100%;text-align:left;border:0;background:none;padding:0">${brkKaart(x,true)}</button>`).join("")}</div>`}
function brkDet(r){const L=brkVoor(r.tk);return L.length?`<div class="sec" style="margin-top:8px">${L.map(x=>brkKaart(x,false)).join("")}</div>`:""}

function brkBand(r){return "";const L=brkVoor(r.tk);return L.map(x=>`<button data-d="${r.tk}" style="display:block;width:100%;text-align:left;margin:8px 0;padding:10px 12px;border:0;border-left:4px solid var(--bad,#c0392b);border-radius:8px;background:color-mix(in srgb,var(--bad,#c0392b) 10%,transparent);color:inherit;font:inherit"><div style="color:var(--bad,#c0392b);font-weight:700;font-size:13px">Belangrijk nieuws · ${new Date(x.datum).toLocaleDateString("nl-NL",{day:"numeric",month:"long"})}</div><div style="font-weight:600;margin-top:2px">${x.titel}</div><div class="note" style="margin:4px 0 0">Tik voor de details en bronnen ›</div></button>`).join("")}

function zoneTile0(r){return r.peh==null||r.fin?"":zoneTile0(r)}
function dBody(k){const o=dtab;dtab=k;let s;try{s=vDet0()}finally{dtab=o}const i=s.indexOf('role="tablist">'),j=s.indexOf('</div>',i)+6;let b=s.slice(j);if(demo&&b.endsWith(demo))b=b.slice(0,-demo.length);return b}
const DT_MAP={analyse:"ov",kwaliteit:"cijfers",waardering:"cijfers",dividend:"cijfers",trend:"koers",ai:"bedrijf",moat:"bedrijf",nieuws:"nieuws",positie:"positie"};
const DT_TABS=[["ov","Overzicht"],["cijfers","Cijfers"],["koers","Koers"],["bedrijf","Bedrijf"],["nieuws","Nieuws"],["positie","Mijn positie"]];
function nlFix(s){return s.replace(/(\d)\.(\d+)(?=%|×)/g,"$1,$2")}
function cutDiv(s,mk){const i=s.indexOf(mk);if(i<0)return s;let d=0,p=i;const re=/<div\b|<\/div>/g;re.lastIndex=i;let m;while((m=re.exec(s))){if(m[0]==="</div>"){d--;if(d===0){return s.slice(0,i)+s.slice(m.index+6)}}else d++}return s}
function finFix(r,s){if(!r.fin)return s;s=s.replace(/<div class="fact"><small>FCF-groei per jaar<\/small>[\s\S]*?<\/div>/,"");s=s.replace(/<div class="fact"><small>Schuld \/ EBITDA<\/small>[\s\S]*?<\/div>/,`<div class="fact"><small>ROE</small><b class="num">${r.roe==null?"–":f1(r.roe)+"%"}</b><em>rendement op eigen vermogen, doel ${RULES.roe}%</em></div>`);return cutDiv(s,'<div class="chart"><h3>Vrije kasstroom (FCF)</h3>')}
function dH(t){return `<div class="sec" style="margin-bottom:0"><h2>${t}</h2></div>`}
function nwsFilter(r,s){return s}
function vDet(){
 const r=rows.find(x=>x.tk===det);let t=DT_MAP[dtab]||dtab;if(!DT_TABS.some(x=>x[0]===t))t="ov";
 let b="";
 if(t==="ov")b=brkDet(r)+analyseTab(r);
 else if(t==="cijfers")b=dqTile(r)+ettmTile(r)+(r.fin?"":kasTile(r))+dH("Groei en kwaliteit")+finFix(r,dBody("kwaliteit"))+dH("Waardering")+dBody("waardering")+dH("Dividend")+dBody("dividend");
 else if(t==="koers")b=dBody("trend");
 else if(t==="bedrijf")b=omsTile(r)+dBody("ai")+moatTab(r);
 else if(t==="nieuws")b=dBody("nieuws");
 else if(t==="positie")b=dBody("positie")+moatTab(r,"pos");
 if(t==="cijfers")b+=ovnTile(r);
 b=nlFix(b);
 return `<div class="bar"><button class="back" id="bk">‹ Terug</button><button class="pill ${r.licht}" data-dx="scoreUit" aria-expanded="${!!dOpen.scoreUit}" style="border:0;font:inherit;font-size:inherit;cursor:pointer">${lichtTxt[r.licht]} · ${r.score}/10 ${dOpen.scoreUit?"˄":"˅"}</button></div>
 <h1 style="font-size:26px;letter-spacing:-.01em">${r.naam}</h1><div class="note" style="margin-top:2px">${r.tk} · ${r.sector} · ${r.land}</div>${dOpen.scoreUit?scoreUitleg(r):""}
 <div class="tabs" role="tablist" style="display:grid;grid-template-columns:repeat(3,1fr);gap:4px;overflow:visible">${DT_TABS.map(([k,n])=>`<button role="tab" data-dt="${k}" aria-selected="${k===t}" style="padding:9px 4px;white-space:nowrap">${n}</button>`).join("")}</div>${b}${demo}`}
const NWS=buildNws();
const TYP={zone:["Koopzone","g"],shortlist:["Shortlist","g"],oordeel:["Oordeel","g"],koersdoel:["Koersdoel","n"],aankondiging:["Aankondiging","a"],insider:["Insider","g"],trend:["Trend","a"],dividend:["Dividend","g"],weging:["Weging","a"],ai:["AI","n"],cijfers:["Cijfers","n"],nieuws:["Nieuws","n"]};
