function vNws(){
 const seg=`<div class="seg seg2" style="margin-top:12px"><button data-nt="feed" aria-pressed="${nwsTab==="feed"}">Nieuws</button><button data-nt="inst" aria-pressed="${nwsTab==="inst"}">Instellingen</button></div>`;
 if(nwsTab==="inst")return head("Nieuws")+seg+vMeld();
 const nw=NWS.filter(x=>x.n),ev=NWS.filter(x=>!x.n);
 return head("Nieuws")+seg+`<div class="sh" style="margin-top:12px"><span class="note" style="margin:0">${unread()?unread()+" nieuw":"Alles gelezen"}</span>${unread()?'<button class="chip" id="readAll">Alles als gelezen</button>':""}</div><div class="sec"><div class="list"><button class="row" data-dx="nbl" aria-expanded="${!dOpen.nbl}"><span class="grow"><div class="t">Belangrijk</div><div class="m">${NWS.filter(x=>x.p).length} berichten</div></span><span class="m">${dOpen.nbl?"˅":"˄"}</span></button>${dOpen.nbl?"":(NWS.filter(x=>x.p).map(nwsRow).join("")||'<div class="row"><span class="grow m">Niets belangrijks op dit moment.</span></div>')}</div></div><div class="sec"><div class="list"><button class="row" data-dx="nov" aria-expanded="${!!dOpen.nov}"><span class="grow"><div class="t">Overig nieuws</div><div class="m">${NWS.filter(x=>!x.p).length} berichten</div></span><span class="m">${dOpen.nov?"˄":"˅"}</span></button>${dOpen.nov?NWS.filter(x=>!x.p).map(nwsRow).join(""):""}</div></div><div class="note">Voor Europese bedrijven komt dit vooral uit nieuwsbronnen en is het minder volledig dan voor Amerikaanse. De bron staat bij elk bericht. Voorbeeldberichten.</div>`+demo}
function nieuwStrip(){const l=NWS.filter(x=>x.p&&x.n&&x.t!=="cijfers"&&x.t!=="nieuws"&&!READ.includes(x.id)).slice(0,2);if(!l.length)return "";
 return `<div class="sec"><div class="sh"><button data-t="nws" style="background:none;border:0;padding:0;margin:0;text-align:left;flex:1;color:inherit;font:inherit;cursor:pointer"><h2>Nieuw</h2></button><button class="chip" data-t="nws">Alles ›</button></div><div class="list">${l.map(x=>`<button class="row" data-d="${x.tk}"><span class="grow"><div class="t" style="white-space:normal">${nameOf(x.tk)}: ${x.h}</div><div class="m"><span class="pill ${TYP[x.t][1]}">${TYP[x.t][0]}</span> ${x.w}</div></span><span class="m">›</span></button>`).join("")}</div></div>`}
const TR=buildTR();
