 groei:[["eps","Winst",r=>({t:epsT(r),c:!epsOk(r)?"n":r.eps>=DOEL?"g":r.eps>=12?"a":"r"}),r=>-r.eps],["fcf","FCF",r=>({t:r.fcf==null?"–":r.fcf+"%",c:r.fcf==null?"n":r.fcf>=12?"g":r.fcf>=8?"a":"r"}),r=>-(r.fcf==null?-99:r.fcf)],["koers","Koers 5j",r=>{const c=cg5(r);return {t:f1(c)+"%",c:c>=DOEL?"g":c>=10?"a":"r"}},r=>-cg5(r)],["gap","Verwacht",r=>{const f=r.epsF;return f==null?{t:"–",c:"n"}:{t:f+"%",sub:"analisten",c:f>=DOEL?"g":f>=12?"a":"r"}},r=>-(r.epsF==null?-99:r.epsF)]],
