 const gr=[["Voldoet","g",v.filter(x=>["voldoet","tijdelijk"].includes(x.v.k))],["Volgen","a",v.filter(x=>["duur","licht"].includes(x.v.k))],["Heroverwegen","r",verk]].map(([n,c,l])=>({n,c,l,w:l.reduce((t,x)=>t+x.r.w,0)}));
