 <div class="s" style="display:flex;flex-wrap:wrap;gap:4px 14px">${gr.map(g=>`<span><span class="sw3" style="background:var(--${g.c==="g"?"good":g.c==="a"?"warn":"bad"})"></span>${g.n} ${g.l.length} · ${f1(g.w/tw*100)}%</span>`).join("")}</div>
