  const i2t={};Object.keys(PRIVE.hold).forEach(t=>i2t[PRIVE.hold[t].isin]=t);
  const raw={};PRIVE.imp.trx.x.forEach(x=>{if(x[5]&&isFinite(x[6]))(raw[x[4]]=raw[x[4]]||[]).push(x)});
  const tr={},pp={},sp={};
